func (this *Bit2c) fetchTradesBody(ch chan AsyncResult[[]Trade], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var optionValue *string = this.SafeString(this.Options, "fetchTradesMethod")                                                // kept here for backward compatibility #29154
	var method *string = this.SafeString(this.HandleOptionAndParams(map[string]any{}, "fetchTrades", "method", optionValue), 0) // publicGetExchangesPairTrades or publicGetExchangesPairLasttrades
	var request map[string]any = map[string]any{
		"pair": market["id"],
	}
	if since != nil {
		request["date"] = this.ParseToInt(since)
	}
	if limit != nil {
		request["limit"] = limit // max 100000
	}
	var responseList []any = []any{}
	if (method != nil && *method == "publicGetExchangesPairTrades") || (method != nil && *method == "public_get_exchanges_pair_trades") {

		r1 := <-this.PublicGetExchangesPairTrades(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response := r1.Raw
		//
		//     [
		//         {"date":1651785980,"price":127975.68,"amount":0.3750321,"isBid":true,"tid":1261018},
		//         {"date":1651785980,"price":127987.70,"amount":0.0389527820303982335802581029,"isBid":true,"tid":1261020},
		//         {"date":1651786701,"price":128084.03,"amount":0.0015614749161156156626239821,"isBid":true,"tid":1261022},
		//     ]
		//
		if IsString(response) {
			panic(ExchangeError(response))
		}
		responseList = this.ToArray(response)
	} else {

		r2 := <-this.PublicGetExchangesPairLasttrades(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response := r2.Raw
		if IsString(response) {
			panic(ExchangeError(response))
		}
		responseList = this.ToArray(response)
	}

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(responseList, market, since, limit))}
	return nil
}

/**
 * @method
 * @name bit2c#fetchTradingFees
 * @description fetch the trading fees for multiple markets
 * @see https://bit2c.co.il/home/api#balance
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
 */
func (this *Bit2c) FetchTradingFeesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]TradingFeeInterface] {
	ch := make(chan AsyncResult[map[string]TradingFeeInterface], 1)
	go this.fetchTradingFeesBody(ch, optionalArgs...)
	return ch
}
func (this *Bit2c) fetchTradingFeesBody(ch chan AsyncResult[map[string]TradingFeeInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.PrivateGetAccountBalance(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "AVAILABLE_NIS": 0.0,
	//         "NIS": 0.0,
	//         "LOCKED_NIS": 0.0,
	//         "AVAILABLE_BTC": 0.0,
	//         "BTC": 0.0,
	//         "LOCKED_BTC": 0.0,
	//         ...
	//         "Fees": {
	//             "BtcNis": { "FeeMaker": 1.0, "FeeTaker": 1.0 },
	//             "EthNis": { "FeeMaker": 1.0, "FeeTaker": 1.0 },
	//             ...
	//         }
	//     }
	//
	var fees map[string]any = SafeMapTyped(response, "Fees")
	var keys []string = nil
	if fees != nil {
		keys = make([]string, 0, len(fees))
		for objectKey := range fees {
			keys = append(keys, objectKey)
		}
	}
	var result map[string]any = map[string]any{}
	for i := 0; i < len(keys); i++ {
		var marketId string = keys[i]
		var symbol *string = this.SafeSymbol(marketId)
		var fee map[string]any = SafeMapTyped(fees, marketId)
		var makerString *string = this.SafeString(fee, "FeeMaker")
		var takerString *string = this.SafeString(fee, "FeeTaker")
		var maker *float64 = this.ParseNumber(Precise.StringDiv(makerString, "100"))
		var taker *float64 = this.ParseNumber(Precise.StringDiv(takerString, "100"))
		if symbol != nil {
			result[*symbol] = map[string]any{
				"info":       fee,
				"symbol":     symbol,
				"taker":      taker,
				"maker":      maker,
				"percentage": true,
				"tierBased":  true,
			}
		}
	}

	ch <- AsyncResult[map[string]TradingFeeInterface]{Value: TradingFeeInterfaceMapFromMap(result)}
	return nil
}

/**
 * @method
 * @name bit2c#createOrder
 * @description create a trade order
 * @see https://bit2c.co.il/home/api#addo
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bit2c) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Bit2c) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"Amount": amount,
		"Pair":   market["id"],
	}
	var response map[string]any = nil
	if typeVar == "market" {
		if side == "buy" {

			r1 := <-this.PrivatePostOrderAddOrderMarketPriceBuy(this.Extend(request, params))
			if r1.Err != nil {
				panic(r1.Err)
			}
			response = r1.Value
		} else {

			r2 := <-this.PrivatePostOrderAddOrderMarketPriceSell(this.Extend(request, params))
			if r2.Err != nil {
				panic(r2.Err)
			}
			response = r2.Value
		}
	} else {
		request["Price"] = price
		var amountString *string = this.NumberToString(amount)
		var priceString *string = this.NumberToString(price)
		request["Total"] = this.ParseToNumeric(Precise.StringMul(amountString, priceString))
		request["IsBid"] = (side == "buy")

		r3 := <-this.PrivatePostOrderAddOrder(this.Extend(request, params))
		if r3.Err != nil {
			panic(r3.Err)
		}
		response = r3.Value
	}

	ch <- AsyncResult[Order]{Value: this.ParseOrder(response, market)}
	return nil
}

