func (this *Bit2c) RemoveCommaFromValue(str string) any {
	var newString any = ""
	var strParts []string = strings.Split(str, ",")
	for i := 0; i < len(strParts); i++ {
		newString = Add(newString, strParts[i])
	}
	return newString
}
func (this *Bit2c) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// public fetchTrades
	//
	//     {
	//         "date":1651785980,
	//         "price":127975.68,
	//         "amount":0.3750321,
	//         "isBid":true,
	//         "tid":1261018
	//     }
	//
	// private fetchMyTrades
	//
	//     {
	//         "ticks":1574767951,
	//         "created":"26/11/19 13:32",
	//         "action":1,
	//         "price":"1,000",
	//         "pair":"EthNis",
	//         "reference":"EthNis|10867390|10867377",
	//         "fee":"0.5",
	//         "feeAmount":"0.08",
	//         "feeCoin":"₪",
	//         "firstAmount":"-0.015",
	//         "firstAmountBalance":"9",
	//         "secondAmount":"14.93",
	//         "secondAmountBalance":"130,233.28",
	//         "firstCoin":"ETH",
	//         "secondCoin":"₪"
	//         "isMaker": True,
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = nil
	var id *string = nil
	var price any = nil
	var amount *string = nil
	var orderId any = nil
	var fee map[string]any = nil
	var side any = nil
	var makerOrTaker *string = nil
	var tradeMarket map[string]any = nil
	var reference *string = this.SafeString(trade, "reference")
	if reference != nil {
		id = reference
		timestamp = this.SafeTimestamp(trade, "ticks")
		var rawPrice *string = this.SafeString(trade, "price")
		if rawPrice != nil {
			price = this.RemoveCommaFromValue(*rawPrice)
		}
		amount = this.SafeString(trade, "firstAmount")
		var reference_parts []string = strings.Split(*reference, "|") // reference contains 'pair|orderId_by_taker|orderId_by_maker'
		var marketId *string = this.SafeString(trade, "pair")
		var marketByPair map[string]any = this.SafeMarket(marketId, market)
		tradeMarket = this.SafeMarket(reference_parts[0], marketByPair)
		var isMaker *bool = this.SafeBool(trade, "isMaker")
		makerOrTaker = SafeStringPtr(func() string {
			if isMaker != nil && *isMaker == true {
				return "maker"
			}
			return "taker"
		}())
		orderId = func() any {
			if isMaker != nil && *isMaker == true {
				return func() any {
					if 2 >= 0 && 2 < len(reference_parts) {
						return reference_parts[2]
					}
					return nil
				}()
			}
			return func() any {
				if 1 >= 0 && 1 < len(reference_parts) {
					return reference_parts[1]
				}
				return nil
			}()
		}()
		var action *int64 = this.SafeInteger(trade, "action")
		if action != nil && *action == 0 {
			side = "buy"
		} else {
			side = "sell"
		}
		var feeCost *string = this.SafeString(trade, "feeAmount")
		if feeCost != nil {
			fee = map[string]any{
				"cost":     feeCost,
				"currency": "NIS",
			}
		}
	} else {
		timestamp = this.SafeTimestamp(trade, "date")
		id = this.SafeString(trade, "tid")
		price = DerefScalar(this.SafeString(trade, "price"))
		amount = this.SafeString(trade, "amount")
		tradeMarket = this.SafeMarket(nil, market)
		side = this.SafeValue(trade, "isBid")
		if side != nil {
			// safeValue already drops an empty string, so a present isBid is a buy here
			side = "buy"
		}
	}
	var marketResolved map[string]any = this.SafeMarket(nil, tradeMarket)
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       marketResolved["symbol"],
		"order":        orderId,
		"type":         nil,
		"side":         side,
		"takerOrMaker": makerOrTaker,
		"price":        price,
		"amount":       amount,
		"cost":         nil,
		"fee":          fee,
	}, marketResolved)
}
func (this *Bit2c) IsFiat(code string) bool {
	return (code == "NIS")
}

/**
 * @method
 * @name bit2c#fetchDepositAddress
 * @description fetch the deposit address for a currency associated with this account
 * @see https://bit2c.co.il/home/api#addc
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Bit2c) FetchDepositAddressAsync(code string, optionalArgs ...any) <-chan AsyncResult[DepositAddress] {
	ch := make(chan AsyncResult[DepositAddress], 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Bit2c) fetchDepositAddressBody(ch chan AsyncResult[DepositAddress], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	if this.IsFiat(code) {
		panic(NotSupported(this.Id + " fetchDepositAddress() does not support fiat currencies"))
	}
	var request map[string]any = map[string]any{
		"Coin": currency["id"],
	}

	r1 := <-this.PrivatePostFundsAddCoinFundsRequest(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//     {
	//         "address": "0xf14b94518d74aff2b1a6d3429471bcfcd3881d42",
	//         "hasTx": False
	//     }
	//
	ch <- AsyncResult[DepositAddress]{Value: this.ParseDepositAddress(response, currency)}
	return nil
}
func (this *Bit2c) ParseDepositAddress(depositAddress any, optionalArgs ...any) DepositAddress {
	//
	//     {
	//         "address": "0xf14b94518d74aff2b1a6d3429471bcfcd3881d42",
	//         "hasTx": False
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var address *string = this.SafeString(depositAddress, "address")
	this.CheckAddress(address)
	var code *string = this.SafeCurrencyCode(nil, currency)
	return DepositAddressFromMap(map[string]any{
		"info":     depositAddress,
		"currency": code,
		"network":  nil,
		"address":  address,
		"tag":      nil,
	})
}
func (this *Bit2c) Nonce() int64 {
	return this.Milliseconds()
}
func (this *Bit2c) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiUrl *string = this.SafeString(this.Urls["api"], "rest")
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + "/" + this.ImplodeParams(path, params)
	var requestBody *string = nil
	var requestHeaders any = nil
	if api[0] == "public" {
		url += ".json"
	} else {
		this.CheckRequiredCredentials()
		// bit2c requires an increasing nonce per key
		var nonce int64 = this.IncrementingNonce()
		var query map[string]any = this.Extend(map[string]any{
			"nonce": nonce,
		}, params)
		var auth string = this.Urlencode(query)
		if method == "GET" {
			if len(query) > 0 {
				url += "?" + auth
			}
		} else {
			requestBody = SafeStringPtr(auth)
		}
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha512, "base64")
		requestHeaders = map[string]any{
			"Content-Type": "application/x-www-form-urlencoded",
			"key":          this.ApiKey,
			"sign":         signature,
		}
	}
	var bodyResult *string = requestBody
	var headersResult any = requestHeaders
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResult,
		"headers": headersResult,
	}
}
func (this *Bit2c) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	//
	//     { "error" : "please approve new terms of use on site." }
	//     { "error": "Please provide valid nonce in Request Nonce (1598218490) is not bigger than last nonce (1598218490)."}
	//     { "Error" : "No order found." }
	//
	var error *string = this.SafeString(response, "error")
	if error == nil {
		error = this.SafeString(response, "Error")
	}
	if error != nil {
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], error, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewBit2c(userConfig map[string]any) *Bit2c {
	p := newBit2c()
	p.Init(userConfig)
	return p
}

func (this *Bit2c) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

